"""Independent naive reference model: own topology maths + brute-force semantics."""
import json, math
from collections import deque

class Invalid(Exception):
    pass

def _pairs(items):
    obj = {}
    for k, v in items:
        if k in obj:
            raise Invalid('duplicate key')
        obj[k] = v
    return obj

def _const(s):
    raise Invalid('nonfinite')

def _float(s):
    x = float(s)
    if not math.isfinite(x):
        raise Invalid('nonfinite')
    return x

def parse(text):
    if text.startswith('\ufeff'):
        raise Invalid('bom')
    try:
        return json.loads(text, object_pairs_hook=_pairs, parse_constant=_const, parse_float=_float)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')

# ------------------------------------------------------------------ topology
def clos_graph(k, intra):
    r = k // 2
    t = k * r
    endpoints = list(range(t))
    cache = set(range(2 * t))
    def footprint(src, dst):
        nodes = {src, dst}
        nodes |= set(range(t + (src // r) * r, t + (src // r) * r + r))
        nodes |= set(t + (dst // r) * r, t + (dst // r) * r + r)
        return frozenset(nodes & cache)
    def pairs_gen():
        for src in endpoints:
            for dst in endpoints:
                if src == dst:
                    continue
                if not intra and src // r == dst // r:
                    continue
                yield src, dst
    def domain(src, dst):
        return src
    return endpoints, cache, footprint, pairs_gen, domain

def clos_pods(k):
    return k // 2

def leaf_spine_model(leaves, spines):
    n = leaves + spines
    adj = [[] for _ in range(n)]
    for l in range(leaves):
        for s in range(leaves, n):
            adj[l].append(s); adj[s].append(l)
    cache = set(range(leaves))
    endpoints = list(range(leaves))
    return graph_model(adj, cache, endpoints, lambda src, dst: src)

def torus2d_model(side):
    n = side * side
    adj = [[] for _ in range(n)]
    for v in range(n):
        x, y = v % side, v // side
        for nx, ny in ((x + 1) % side, y), ((x - 1) % side, y), (x, (y + 1) % side), (x, (y - 1) % side):
            u = ny * side + nx
            if u not in adj[v]:
                adj[v].append(u)
    cache = set(range(n))
    return graph_model(adj, cache, list(range(n)), lambda src, dst: src)

def torus2d_row(side):
    return lambda src, dst: src // side

def torus3d_model(side):
    n = side ** 3
    adj = [[] for _ in range(n)]
    for v in range(n):
        x = v % side
        y = (v // side) % side
        z = v // (side * side)
        for (nx, ny, nz) in (((x + 1) % side, y, z), ((x - 1) % side, y, z),
                             (x, (y + 1) % side, z), x, (y - 1) % side, z) if False else []:
            pass
        cand = [((x + 1) % side, y, z), ((x - 1) % side, y, z),
                (x, (y + 1) % side, z), (x, (y - 1) % side, z),
                (x, y, (z + 1) % side), (x, y, (z - 1) % side)]
        for (nx, ny, nz) in cand:
            u = (nz * side + ny) * side + nx
            if u not in adj[v]:
                adj[v].append(u)
    cache = set(range(n))
    return graph_model(adj, cache, list(range(n)), lambda src, dst: src)

def torus3d_line(side):
    return lambda src, dst: src // side

def dragonfly_model(g, a, h):
    n = g * a
    adj = [[] for _ in range(n)]
    def rid(group, idx):
        return group * a + idx
    for group in range(g):
        for i in range(a):
            for j in range(i + 1, a):
                adj[rid(group, i)].append(rid(group, j))
                adj[rid(group, j)].append(rid(group, i))
    for g1 in range(g):
        for g2 in range(g1 + 1, g):
            delta = (g2 + g - g1) % g
            rev = g - delta
            adj[rid(g1, (delta - 1) // h)].append(rid(g2, (rev - 1) // h))
            adj[rid(g2, (rev - 1) // h)].append(rid(g1, (delta - 1) // h))
    for v in adj:
        v.sort()
        del v[::2] if False else None
        seen = set(); v[:] = [x for x in v if not (x in seen or seen.add(x))]
    cache = set(range(n))
    return graph_model(adj, cache, list(range(n)), lambda src, dst: src)

def dragonfly_domains(g, a):
    return {'router': lambda src, dst: src,
            'group': lambda src, dst: src // a,
            'target': lambda src, dst: src * g + dst // a}

def dfplus_model(g, l, s, h, dense):
    per = l + s
    n = g * per
    adj = [[] for _ in range(n)]
    def lid(group, leaf):
        return group * per + leaf
    def sid(group, spine):
        return group * per + l + spine
    def add(u, v):
        adj[u].append(v); adj[v].append(u)
    for group in range(g):
        for leaf in range(l):
            for spine in range(s):
                add(lid(group, leaf), sid(group, spine))
    if dense:
        for g1 in range(g):
            for g2 in range(g1 + 1, g):
                for spine in range(s):
                    add(sid(g1, spine), sid(g2, spine))
    else:
        for g1 in range(g):
            for g2 in range(g1 + 1, g):
                delta = (g2 + g - g1) % g
                rev = g - delta
                add(sid(g1, (delta - 1) // h), sid(g2, (rev - 1) // h))
    for v in adj:
        seen = set(); v[:] = [x for x in v if not (x in seen or seen.add(x))]
    leaves = [lid(group, leaf) for group in range(g) for leaf in range(l)]
    cache = set(range(n))
    dom_group = lambda src, dst: src // per
    dom_tor = lambda src, dst: (src // per) * l + (src % per)
    return graph_model(adj, cache, leaves, dom_group), dom_tor

def graph_model(adj, cache, endpoints, domain):
    n = len(adj)
    dist = []
    for src in range(n):
        d = [-1] * n
        d[src] = 0
        q = deque([src])
        while q:
            v = q.popleft()
            for u in adj[v]:
                if d[u] < 0:
                    d[u] = d[v] + 1
                    q.append(u)
        dist.append(d)
    def footprint(src, dst):
        target = dist[src][dst]
        assert target >= 0, 'disconnected'
        return frozenset(v for v in range(n) if v in cache and dist[src][v] + dist[v][dst] == target)
    def pairs_gen():
        for src in endpoints:
            for dst in endpoints:
                if src != dst:
                    yield src, dst
    return n, footprint, pairs_gen, domain

class Topo:
    def __init__(self, spec):
        mode = spec[0]
        self.mode = mode
        self.domains = []
        self.foots = []
        self.srcs = []
        self.dsts = []
        if mode == 'clos':
            k, scope, intra = spec[1], spec[2], spec[3]
            r = k // 2
            t = k * r
            self.n = k * k
            self.cache = set(range(2 * t))
            for src, dst in clos_pairs(k, intra):
                fp = {src, dst}
                fp |= set(range(t + (src // r) * r, t + (src // r) * r + r))
                fp |= set(range(t + (dst // r) * r, t + (dst // r) * r + r))
                self.foots.append(frozenset(fp))
                self.srcs.append(src); self.dsts.append(dst)
                self.domains.append(src if scope == 'tor' else src // r)
        elif mode == 'leaf-spine':
            leaves, spines = spec[1], spec[2]
            n, footprint, pairs_gen, domain = leaf_spine_model(leaves, spines)
            self.n = n
            self.finish(pairs_gen, footprint, domain)
        elif mode == 'torus2d':
            side, scope = spec[1], spec[2]
            n, footprint, pairs_gen, domain = torus2d_model(side)
            dom = domain if scope == 'host' else torus2d_row(side)
            self.n = n
            self.finish(pairs_gen, footprint, dom)
        elif mode == 'torus3d':
            side, scope = spec[1], spec[2]
            n, footprint, pairs_gen, domain = torus3d_model(side)
            dom = domain if scope == 'host' else torus3d_line(side)
            self.n = n
            self.finish(pairs_gen, footprint, dom)
        elif mode == 'dragonfly':
            g, a, h, scope = spec[1], spec[2], spec[3], spec[4]
            self.n, footprint, pairs_gen, domain = dragonfly_model(g, a, h)
            dom = dragonfly_domains(g, a)[scope]
            self.finish(pairs_gen, footprint, dom)
        elif mode == 'dragonfly-plus':
            g, l, s, h, dense, scope = spec[1], spec[2], spec[3], spec[4], spec[5], spec[6]
            (self.n, footprint, pairs_gen, domain), dom_tor = dfplus_model(g, l, s, h, dense)
            dom = dom_tor if scope == 'tor' else domain
            self.finish(pairs_gen, footprint, dom)
        else:
            raise Invalid('topology mode')
        assert self.n <= 343

    def finish(self, pairs_gen, footprint, domain):
        for src, dst in pairs_gen():
            self.foots.append(footprint(src, dst))
            self.srcs.append(src); self.dsts.append(dst)
            self.domains.append(domain(src, dst))

def clos_pairs(k, intra):
    r = k // 2
    t = k * r
    for src in range(t):
        for dst in range(t):
            if src == dst:
                continue
            if not intra and src // r == dst // r:
                continue
            yield src, dst

# ---------------------------------------------------------------- validation
def I(x, lo, hi):
    if type(x) is not int or not (lo <= x <= hi):
        raise Invalid('range')
    return x

def list_of(x, cap):
    if not isinstance(x, list) or len(x) > cap:
        raise Invalid('list')
    return x

def exact(obj, *names):
    if not isinstance(obj, dict) or set(obj) != set(names):
        raise Invalid('keys')
    return obj

def check(cond):
    if not cond:
        raise Invalid('schema')

def validate(request):
    exact(request, 'version', 'sessions')
    I(request['version'], 2, 2)
    sessions = list_of(request['sessions'], 16)
    tasks_total = edits_total = tx_total = 0
    state = []
    qtotal = 0

    def getq(q, g, n, d):
        nonlocal qtotal
        exact(q, 'groups', 'nodes', 'tasks')
        out = []
        for key, cap in (('groups', g), ('nodes', n), ('tasks', d)):
            lst = list_of(q[key], 200000)
            for x in lst:
                I(x, 0, cap - 1)
            out.append(list(lst))
            qtotal += len(lst)
        return out

    for s in sessions:
        exact(s, 'topology', 'caps', 'groups', 'tasks', 'query', 'transactions')
        spec = s['topology']
        list_of(spec, 8)
        topo = Topo(spec)
        n = topo.n
        tcount = len(topo.foots)
        caps = list_of(s['caps'], n)
        check(len(caps) == n)
        for c in caps:
            I(c, 0, 10 ** 9)
        groups = list_of(s['groups'], 8192)
        check(len(groups) >= 1)
        g = len(groups)
        grows = []
        for row in groups:
            list_of(row, 2)
            check(len(row) == 2)
            grows.append((I(row[0], 0, 64), I(row[1], 1, 10 ** 12)))
        tasks = list_of(s['tasks'], 100000)
        d = len(tasks)
        trows = []
        for row in tasks:
            list_of(row, 5)
            check(len(row) == 5)
            trows.append((I(row[0], 0, tcount - 1), I(row[1], 0, g - 1), I(row[2], 1, 10 ** 9),
                          I(row[3], 0, 10 ** 9), I(row[4], 0, 1)))
        q0 = getq(s['query'], g, n, d)
        txs = list_of(s['transactions'], 50000)
        tx_total += len(txs)
        ops = 0
        bout = []
        for tx in txs:
            exact(tx, 'revision', 'edits', 'query')
            I(tx['revision'], 0, 10 ** 9)
            edits = list_of(tx['edits'], 100000)
            ops += len(edits)
            elist = []
            for e in edits:
                list_of(e, 3)
                check(len(e) == 3 and isinstance(e[0], str))
                op, idx, value = e
                tables = {'move': (d, 0, g - 1), 'weight': (d, 1, 10 ** 9), 'class': (d, 0, 10 ** 9),
                          'bind': (d, 0, tcount - 1), 'pin': (d, 0, 1), 'quota': (g, 0, 64),
                          'budget': (g, 1, 10 ** 12), 'cap': (n, 0, 10 ** 9)}
                check(op in tables)
                cap, lo, hi = tables[op]
                I(idx, 0, cap - 1)
                I(value, lo, hi)
                elist.append((op, idx, value))
            bq = getq(tx['query'], g, n, d)
            bout.append((tx['revision'], elist, bq))
        tasks_total += d
        edits_total += ops
        state.append((topo, n, tcount, g, caps, grows, trows, q0, bout))
    check(8 * qtotal + sum((t[2] + len(t[6]) + sum(len(e[1]) for e in t[8])) * t[1] for t in state) <= 128000000)
    check(tasks_total <= 200000 and edits_total <= 100000 and tx_total <= 50000)
    return state

# --------------------------------------------------------------- semantics
class St:
    def __init__(self, topo, caps, grows, trows):
        self.topo = topo
        self.caps = list(caps)
        self.quota = [q for q, b in grows]
        self.budget = [b for q, b in grows]
        self.tasks = [list(r) for r in trows]     # template, group, weight, class, pin
        self.revision = 0

def derive(st):
    g = len(st.quota)
    members = [[] for _ in range(g)]
    for tid, t in enumerate(st.tasks):
        members[t[1]].append(tid)
    foots, loads, keysets = [], [], []
    for m in members:
        u = set(); tot = 0; ks = set()
        for tid in m:
            t = st.tasks[tid]
            u |= st.topo.foots[t[0]]
            tot += t[2]
            ks.add((st.topo.domains[t[0]], t[3]))
        foots.append(frozenset(u)); loads.append(tot); keysets.append(ks)
    usage = [0] * st.topo.n
    for gid in range(g):
        if members[gid]:
            for x in foots[gid]:
                usage[x] += st.quota[gid]
    return members, foots, loads, keysets, usage

def violations(st, begin=None, begin_quota=None):
    members, foots, loads, keysets, usage = derive(st)
    g = len(st.quota)
    capacity = sum(1 for x in range(st.topo.n) if usage[x] > st.caps[x])
    mixed = sum(1 for gid in range(g) if len(keysets[gid]) > 1)
    work = sum(1 for gid in range(g)
               if members[gid] and (st.quota[gid] == 0 or loads[gid] > st.quota[gid] * st.budget[gid]))
    pins = 0
    if begin is not None:
        for tid, t in enumerate(st.tasks):
            bt = begin[tid]
            if bt[4] != 1:
                continue
            bg = bt[1]
            if (t[1] != bt[1] or t[0] != bt[0] or t[2] != bt[2] or t[3] != bt[3]
                    or st.quota[bg] != begin_quota[bg]):
                pins += 1
    return [capacity, mixed, work, pins], members, foots, loads, keysets, usage

def certificate(st, q):
    members, foots, loads, keysets, usage = derive(st)
    g = len(st.quota)
    totals = [sum(1 for gid in range(g) if members[gid]), sum(usage),
              sum(t[2] for t in st.tasks), sum(1 for t in st.tasks if t[4] == 1)]
    grows = []
    for gid in q[0]:
        if members[gid]:
            dom, cls = sorted(keysets[gid])[0] if len(keysets[gid]) == 1 else (-1, -1)
        else:
            dom = cls = -1
        grows.append([gid, len(members[gid]), loads[gid], st.quota[gid], st.budget[gid], len(foots[gid]), dom, cls])
    return {'totals': totals, 'groups': grows,
            'nodes': [[x, usage[x], st.caps[x]] for x in q[1]],
            'tasks': [[tid, t[1], t[0], t[2], t[3], t[4]] for tid, t in
                      ((tid, st.tasks[tid]) for tid in q[2])]}

def run_json(text):
    try:
        request = parse(text)
        state = validate(request)
    except Invalid:
        return '{"error":"invalid"}'
    results = []
    for topo, n, tcount, g, caps, grows, trows, q0, txs in state:
        st = St(topo, caps, grows, trows)
        members, foots, loads, keysets, usage = derive(st)
        bad = any(members[gid] and (len(keysets[gid]) > 1 or st.quota[gid] == 0
                                    or loads[gid] > st.quota[gid] * st.budget[gid]) for gid in range(g))
        bad = bad or any(usage[x] > caps[x] for x in range(n))
        if bad:
            return '{"error":"invalid"}'
        outs = []
        for revision, elist, tq in txs:
            if revision != st.revision:
                outs.append({'accepted': False, 'revision': st.revision, 'violations': None,
                             'certificate': certificate(st, tq)})
                continue
            begin = [list(t) for t in st.tasks]
            bq = list(st.quota)
            bb = list(st.budget)
            bc = list(st.caps)
            for op, idx, value in elist:
                if op == 'move': st.tasks[idx][1] = value
                elif op == 'weight': st.tasks[idx][2] = value
                elif op == 'class': st.tasks[idx][3] = value
                elif op == 'bind': st.tasks[idx][0] = value
                elif op == 'pin': st.tasks[idx][4] = value
                elif op == 'quota': st.quota[idx] = value
                elif op == 'budget': st.budget[idx] = value
                elif op == 'cap': st.caps[idx] = value
            viol = violations(st, begin, bq)[0]
            accepted = all(v == 0 for v in viol)
            if not accepted:
                st.tasks = [list(t) for t in begin]
                st.quota, st.budget, st.caps = bq, bb, bc
            else:
                st.revision += 1
            outs.append({'accepted': accepted, 'revision': st.revision, 'violations': viol,
                         'certificate': certificate(st, tq)})
        results.append({'nodes': n, 'templates': tcount, 'initial': certificate(st, q0),
                        'transactions': outs})
    return json.dumps({'sessions': results}, separators=(',', ':'))

if __name__ == '__main__':
    import sys
    sys.stdout.write(run_json(sys.stdin.read()) + '\n')
